/**
 * 상단 오른쪽 버튼 클릭 이벤트
 */
scwin.sch_cal_onheaderbtnclick = function(retObj) {
    if (retObj.viewType == 'basicDay') {
      sch_cal.changeView("agendaDay");  
    }
};

/**
 * 일정 추가 이벤트
 */
scwin.sch_cal_onclick = function(retObj) {

    console.log(retObj);

    var data = {
        userYn : "Y",
        viewYn : "N",
        startDate: WebSquare.date.getFormattedDate(retObj.start, "yyyy-MM-dd"),
        callbackFn : "scwin.fn_Callback" };
    var options = {
        id : "schedulePopup",
        title : "schedulePopup",
        height : "500px",
        width: "800px",
        modal : true,
        popupName : "일정등록팝업"
    };
    //com.win.openPopup("/ui/sample/scheduleCalendarPopup.xml", options, data);
};
scwin.titleFormatter = function (info) {
    console.log("titleFormatter");
    if (info.title) {
        return "<span>구분</span> " + info.title;
    }
}
scwin.fn_Callback = function (res) {
    var gubunStr = "";
    if (res.gubun == "1") {
        gubunStr = "휴가";
    } else if (res.gubun == "2") {
        gubunStr = "출장";
    } else if (res.gubun == "6") {
        gubunStr = "당직";
    } else if (res.gubun == "7") {
        gubunStr = "공가";
    } else if (res.gubun == "8") {
        gubunStr = "임원";
    } else if (res.gubun == "10") {
        gubunStr = "입사";
    } else if (res.gubun == "11") {
        gubunStr = "퇴사";
    }

    var formatTitle = "<span>" + gubunStr + "</span> " + res.title;

    dataList1.insertJSON(0, [{"start":res.sdate, "end":res.sdate, "id":res.id, "title":formatTitle, "theme":{ "color":"yellow", "textColor":"#000000" } }])
};

